 sendLobby(){if(this.role!=='host')return;const roster=this.members.map(publicMember);for(const entry of this.entries.values())if(entry.link?.open)entry.link.send({t:'party-lobby',build:NET_BUILD,key:this.key,selfId:entry.id,roster,options:this.options,code:this.code,preparing:!!this.pendingMatch});this.change();}
