 chooseFor(member,team){if(this.pendingMatch){this.notice='Teams are locked while vehicles prepare.';this.sendLobby();return false;}const next=team===0||team===1?team:null;if(this.matchId&&this.sim?.phase!=='ended'){this.notice='Team choices are available again after this match.';this.sendLobby();return false;}if(next!==null&&this.members.filter(other=>other.id!==member.id&&other.team===next).length>=4){this.notice='That team already has four players.';this.sendLobby();return false;}member.team=next;member.ready=next===null;member.rematch=false;this.notice='';this.sendLobby();return true;}
