 async startMatch(){if(this.role!=='host'||this.closed||this.pendingMatch)return false;const players=this.players();if(this.sim?.phase==='ended'&&players.some(player=>!this.members.find(member=>member.id===player.id).rematch))return false;if(this.members.some(member=>member.team!==null&&!member.connected))return false;if(!players.length||players.some(player=>!this.members.find(member=>member.id===player.id).ready))return false;const id=crypto.randomUUID();this.pendingMatch=id;this.hostLoaded=false;this.change('starting');this.sendLobby();try{await this.prepare(players.map(player=>player.look.body));if(this.closed||this.pendingMatch!==id)return false;if(players.some(player=>!this.members.some(member=>member.id===player.id&&member.token===player.token&&member.connected&&member.team===player.team))){this.pendingMatch=null;this.notice='A player left during preparation. Ready up and start again.';this.change('lobby');this.sendLobby();return false;}this.makeSimulation(id,players);this.startWaiting=new Set([...this.entries.values()].filter(entry=>entry.link?.open&&!entry.recovering).map(entry=>entry.id));this.hostLoaded=true;for(const entry of this.entries.values())if(this.startWaiting.has(entry.id))this.sendConfig(entry,false);this.maybeGo();this.later(()=>{if(this.pendingMatch===id){this.pendingMatch=null;this.notice='A player could not finish loading. Try Start Match again.';this.change('lobby');this.sendLobby();}},30000);return true;}catch{this.pendingMatch=null;this.notice='A vehicle could not load. Choose another body or try again.';this.change('lobby');this.sendLobby();return false;}}
