 async loadConfig(packet){if(packet.build!==NET_BUILD||typeof packet.matchId!=='string'||!Array.isArray(packet.players)||packet.players.length<1||packet.players.length>8||new Set(packet.players.map(player=>player.id)).size!==packet.players.length||packet.players.some(player=>!Number.isInteger(player.id)||player.id<0||player.id>7||![0,1].includes(player.team))){this.fail('Invalid custom match configuration.');return;}const generation=this.loadGeneration=(this.loadGeneration||0)+1,players=packet.players;this.change('starting');try{await this.prepare(players.map(player=>appearance(player.look).body));if(this.closed||generation!==this.loadGeneration)return;this.options=partyOptions(packet.options);this.makeSimulation(packet.matchId,players);this.sim.localPlayerId=packet.playerId===this.id&&players.some(player=>player.id===this.id)?this.id:null;for(const car of this.sim.cars){const player=players.find(player=>player.id===car.id);if(/^#[a-f0-9]{6}$/i.test(player.color))car.appearance.color=player.color;}this.replica=new GuestReplica(this.sim,this.sim.localPlayerId);if(!this.replica.receive(packet.state,this.clock()))throw Error();this.hostPaused=packet.paused===true;this.replica.paused=this.hostPaused;this.pendingMatch=packet.join?null:packet.matchId;this.link.send({t:packet.join?'party-joined':'party-loaded',matchId:packet.matchId});}catch{this.fail('The custom match or a selected vehicle could not load.');}}
