 ping(entry){entry.pings??=new Map();const id=partySecret().slice(0,12),at=this.clock();entry.pings.set(id,at);while(entry.pings.size>8)entry.pings.delete(entry.pings.keys().next().value);(entry.link||this.link)?.send({t:'ping',id,at,loss:entry.quality.delivery.loss()});}
